-- ==================================base======================================--
-- 添加计算规则字段
ALTER TABLE `service_accounting_base`.`account_fee_configuration`
ADD COLUMN `calculation_rule` varchar(128) NULL COMMENT 'Fee calculation rules' AFTER `product_code`;

ALTER TABLE `service_accounting_base`.`monthly_fee_configuration`
ADD COLUMN `calculation_rule` varchar(128) NULL COMMENT 'Fee calculation rules' AFTER `product_code`;


-- 刪除产品 乘帆-巴西-PAY_IN-EL_CREDIT_CARD
DELETE
FROM `service_accounting_base`.`account_product`
WHERE `id` = 83869193261547529;

-- 删除费用配置 乘帆-巴西-PAY_IN-CREDIT_CARD & 乘帆-巴西-PAY_IN-EL_CREDIT_CARD
DELETE
FROM `service_accounting_base`.`account_fee_configuration`
WHERE `account_product_id` IN (83869193261547528, 83869193261547529);


